20	import * as zrUtil from 'zrender/src/core/util';
21	import ExtensionAPI from '../core/ExtensionAPI';
22	import GlobalModel from '../model/Global';
23	import Model from '../model/Model';
24	import SeriesModel from '../model/Series';
25	import {makeInner} from '../util/model';
26	import {Dictionary, DecalObject, InnerDecalObject, AriaOption} from '../util/types';
27	import {LocaleOption} from '../core/locale';
28	import { getDecalFromPalette } from '../model/mixin/palette';
29	import type {TitleOption} from '../component/title/install';
30	
31	const DEFAULT_OPTION: AriaOption = {
32	    label: {
33	        enabled: true
34	    },
35	    decal: {
36	        show: false
37	    }
38	};
39	
40	const inner = makeInner<{scope: object}, SeriesModel>();
41	
42	const decalPaletteScope: Dictionary<DecalObject> = {};
43	
44	type SeriesTypes = keyof LocaleOption['series']['typeNames'];
45	
46	export default function ariaVisual(ecModel: GlobalModel, api: ExtensionAPI) {
47	    const ariaModel: Model<AriaOption> = ecModel.getModel('aria');
48	
49	    // See "area enabled" detection code in `GlobalModel.ts`.
50	    if (!ariaModel.get('enabled')) {
51	        return;
52	    }
53	
54	    const defaultOption = zrUtil.clone(DEFAULT_OPTION);
55	    zrUtil.merge(defaultOption.label, ecModel.getLocaleModel().get('aria'), false);
56	    zrUtil.merge(ariaModel.option, defaultOption, false);
57	
58	    setDecal();
59	    setLabel();
60	
61	    function setDecal() {
62	        const decalModel = ariaModel.getModel('decal');
63	
64	        const useDecal = decalModel.get('show');
65	        if (useDecal) {
66	            // Each type of series use one scope.
67	            // Pie and funnel are using different scopes.
68	            const paletteScopeGroupByType = zrUtil.createHashMap<object>();
69	            ecModel.eachSeries((seriesModel: SeriesModel) => {
70	                if (seriesModel.isColorBySeries()) {
71	                    return;
72	                }
73	                let decalScope = paletteScopeGroupByType.get(seriesModel.type);
74	                if (!decalScope) {
75	                    decalScope = {};
76	                    paletteScopeGroupByType.set(seriesModel.type, decalScope);
77	                }
78	                inner(seriesModel).scope = decalScope;
79	            });
80	
81	            ecModel.eachRawSeries((seriesModel: SeriesModel) => {
82	                if (ecModel.isSeriesFiltered(seriesModel)) {
83	                    return;
84	                }
85	                if (zrUtil.isFunction(seriesModel.enableAriaDecal)) {
86	                    // Let series define how to use decal palette on data
87	                    seriesModel.enableAriaDecal();
88	                    return;
89	                }
90	
91	                const data = seriesModel.getData();
92	
93	                if (!seriesModel.isColorBySeries()) {
94	                    const dataAll = seriesModel.getRawData();
95	                    const idxMap: Dictionary<number> = {};
96	                    const decalScope = inner(seriesModel).scope;
97	
98	                    data.each(function (idx) {
99	                        const rawIdx = data.getRawIndex(idx);
100	                        idxMap[rawIdx] = idx;
101	                    });
102	
103	                    const dataCount = dataAll.count();
104	                    dataAll.each(rawIdx => {
105	                        const idx = idxMap[rawIdx];
106	                        const name = dataAll.getName(rawIdx) || (rawIdx + '');
107	                        const paletteDecal = getDecalFromPalette(
108	                            seriesModel.ecModel,
109	                            name,
110	                            decalScope,
111	                            dataCount
112	                        );
113	                        const specifiedDecal = data.getItemVisual(idx, 'decal');
114	                        data.setItemVisual(idx, 'decal', mergeDecal(specifiedDecal, paletteDecal));
115	                    });
116	                }
117	                else {
118	                    const paletteDecal = getDecalFromPalette(
119	                        seriesModel.ecModel,
120	                        seriesModel.name,
121	                        decalPaletteScope,
122	                        ecModel.getSeriesCount()
123	                    );
124	                    const specifiedDecal = data.getVisual('decal');
125	                    data.setVisual('decal', mergeDecal(specifiedDecal, paletteDecal));
126	                }
127	
128	                function mergeDecal(specifiedDecal: DecalObject, paletteDecal: DecalObject): DecalObject {
129	                    // Merge decal from palette to decal from itemStyle.
130	                    // User do not need to specify all of the decal props.
131	                    const resultDecal = specifiedDecal
132	                        ? zrUtil.extend(zrUtil.extend({}, paletteDecal), specifiedDecal)
133	                        : paletteDecal;
134	                    (resultDecal as InnerDecalObject).dirty = true;
135	                    return resultDecal;
136	                }
137	            });
138	        }
139	    }
140	
141	    function setLabel() {
142	        const labelLocale = ecModel.getLocaleModel().get('aria');
143	        const labelModel = ariaModel.getModel('label');
144	        labelModel.option = zrUtil.defaults(labelModel.option, labelLocale);
145	
146	        if (!labelModel.get('enabled')) {
147	            return;
148	        }
149	
150	        const dom = api.getZr().dom;
151	        // When in SSR mode, the dom is not available, so just return.
152	        if (!dom) {
153	            return;
154	        }
155	        dom.setAttribute('role', 'img');
156	        if (labelModel.get('description')) {
157	            dom.setAttribute('aria-label', labelModel.get('description'));
158	            return;
159	        }
160	
161	        const seriesCnt = ecModel.getSeriesCount();
162	        const maxDataCnt = labelModel.get(['data', 'maxCount']) || 10;
163	        const maxSeriesCnt = labelModel.get(['series', 'maxCount']) || 10;
164	        const displaySeriesCnt = Math.min(seriesCnt, maxSeriesCnt);
165	
166	        let ariaLabel;
167	        if (seriesCnt < 1) {
168	            // No series, no aria label
169	            return;
170	        }
171	        else {
172	            const title = getTitle();
173	            if (title) {
174	                const withTitle = labelModel.get(['general', 'withTitle']);
175	                ariaLabel = replace(withTitle, {
176	                    title: title
177	                });
178	            }
179	            else {
180	                ariaLabel = labelModel.get(['general', 'withoutTitle']);
181	            }
182	
183	            const seriesLabels: string[] = [];
184	            const prefix = seriesCnt > 1
185	                ? labelModel.get(['series', 'multiple', 'prefix'])
186	                : labelModel.get(['series', 'single', 'prefix']);
187	            ariaLabel += replace(prefix, { seriesCount: seriesCnt });
188	
189	            ecModel.eachSeries(function (seriesModel, idx) {
190	                if (idx < displaySeriesCnt) {
191	                    let seriesLabel;
192	
193	                    const seriesName = seriesModel.get('name');
194	                    const withName = seriesName ? 'withName' : 'withoutName';
195	                    seriesLabel = seriesCnt > 1
196	                        ? labelModel.get(['series', 'multiple', withName])
197	                        : labelModel.get(['series', 'single', withName]);
198	
199	                    seriesLabel = replace(seriesLabel, {
200	                        seriesId: seriesModel.seriesIndex,
201	                        seriesName: seriesModel.get('name'),
202	                        seriesType: getSeriesTypeName(seriesModel.subType as SeriesTypes)
203	                    });
204	
205	                    const data = seriesModel.getData();
206	                    if (data.count() > maxDataCnt) {
207	                        // Show part of data
208	                        const partialLabel = labelModel.get(['data', 'partialData']);
209	                        seriesLabel += replace(partialLabel, {
210	                            displayCnt: maxDataCnt
211	                        });
212	                    }
213	                    else {
214	                        seriesLabel += labelModel.get(['data', 'allData']);
215	                    }
216	
217	                    const middleSeparator = labelModel.get(['data', 'separator', 'middle']);
218	                    const endSeparator = labelModel.get(['data', 'separator', 'end']);
219	                    const dataLabels = [];
220	                    for (let i = 0; i < data.count(); i++) {
221	                        if (i < maxDataCnt) {
222	                            const name = data.getName(i);
223	                            const value = data.getValues(i);
224	                            const dataLabel = labelModel.get(['data', name ? 'withName' : 'withoutName']);
225	                            dataLabels.push(
226	                                replace(dataLabel, {
227	                                    name: name,
228	                                    value: value.join(middleSeparator)
229	                                })
230	                            );
231	                        }
232	                    }
233	                    seriesLabel += dataLabels.join(middleSeparator) + endSeparator;
234	
235	                    seriesLabels.push(seriesLabel);
236	                }
237	            });
238	
239	            const separatorModel = labelModel.getModel(['series', 'multiple', 'separator']);
240	            const middleSeparator = separatorModel.get('middle');
241	            const endSeparator = separatorModel.get('end');
242	            ariaLabel += seriesLabels.join(middleSeparator) + endSeparator;
243	
244	            dom.setAttribute('aria-label', ariaLabel);
245	        }
246	    }
247	
248	    function replace(str: string, keyValues: object) {
249	        if (!zrUtil.isString(str)) {
250	            return str;
251	        }
252	
253	        let result = str;
254	        zrUtil.each(keyValues, function (value: string, key: string) {
255	            result = result.replace(
256	                new RegExp('\\{\\s*' + key + '\\s*\\}', 'g'),
257	                value
258	            );
259	        });
260	        return result;
261	    }
262	
263	    function getTitle() {
264	        let title = ecModel.get('title') as TitleOption | TitleOption[];
265	        if (title && (title as TitleOption[]).length) {
266	            title = (title as TitleOption[])[0];
267	        }
268	        return title && (title as TitleOption).text;
269	    }
270	
271	    function getSeriesTypeName(type: SeriesTypes) {
272	        const typeNames = ecModel.getLocaleModel().get(['series', 'typeNames']);
273	        return typeNames[type] || typeNames.chart;
274	    }
275	}

